/// <summary>
/// PaffH 17.12.24
/// </summary>
public void initValue()
{
    super();

    this.StartupRelease = NDXStartupRelease::Startup;
}

/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <param name = "_prodPoolId">ProdPoolId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdTableProdIdentProdPool</returns>
public static NDXProdTableProdIdentProdPool find(ProdPoolId _prodPoolId, boolean _forUpdate = false)
{
    NDXProdTableProdIdentProdPool nDXProdTableProdIdentProdPool;
    nDXProdTableProdIdentProdPool.selectForUpdate(_forUpdate);
    select firstonly nDXProdTableProdIdentProdPool
        where nDXProdTableProdIdentProdPool.ProdPoolId == _prodPoolId;
    return nDXProdTableProdIdentProdPool;
}

/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <param name = "_record">prodParmStartUp or prodParmRelease</param>
/// <returns>print ProdIdent-QR-Codes for prodPool</returns>
public static NoYes checkPrintProdIdentQRCodesForProdPool(Common _record)
{
    ProdPoolId prodPoolId;
    NDXStartupRelease startUpRelease;
    NDXProdTableProdIdentReport nDXProdTableProdIdentReport;
    boolean printProdIdentQRCodes;

    switch (_record.TableId)
    {
        case (tableNum(ProdParmStartUp)) :
            ProdParmStartUp prodParmStartUp = _record as ProdParmStartUp;
            prodPoolId = prodParmStartUp.prodTable().ProdPoolId;
            nDXProdTableProdIdentReport = NDXProdTableProdIdentReport::find(prodParmStartUp.prodTable().RecId);
            startUpRelease = NDXStartupRelease::Startup;
            break;
        case (tableNum(ProdParmRelease)) :
            ProdParmRelease prodParmRelease = _record as ProdParmRelease;
            prodPoolId = prodParmRelease.prodTable().ProdPoolId; 
            nDXProdTableProdIdentReport = NDXProdTableProdIdentReport::find(prodParmRelease.prodTable().RecId);
            startUpRelease = NDXStartupRelease::Release;
            break;
        default :
            throw error(Error::wrongUseOfFunction(funcName()));
    }

    NDXProdIdentControlPanelParameters nDXProdIdentControlPanelParameters = NDXProdIdentControlPanelParameters::find();
    printProdIdentQRCodes = (nDXProdIdentControlPanelParameters.ProdIdentReportProdDefault == NoYes::Yes);
    printProdIdentQRCodes = printProdIdentQRCodes && !nDXProdTableProdIdentReport.printed();
    if (printProdIdentQRCodes)
    {
        if (nDXProdIdentControlPanelParameters.ProdIdentReportProdPool == NoYes::Yes)
        {
            NDXProdTableProdIdentProdPool nDXProdTableProdIdentProdPool = NDXProdTableProdIdentProdPool::find(ProdPoolId);
            printProdIdentQRCodes = (nDXProdTableProdIdentProdPool.RecId != 0);
            if (printProdIdentQRCodes)
            {
                printProdIdentQRCodes = 
                    (nDXProdTableProdIdentProdPool.StartupRelease == NDXStartupRelease::WithoutSpecification ||
                    nDXProdTableProdIdentProdPool.StartupRelease == startUpRelease);
            }
        }
    }

    return (printProdIdentQRCodes ? NoYes::Yes : NoYes::No);
}
